    /**
     * Devuelve el SVG embebido con atributos opcionales.
     *
     * @param string $name  Nombre del icono (clave en el array).
     * @param array  $attrs Atributos HTML adicionales: class, width, height, aria-hidden, etc.
     * @return string       SVG completo o cadena vacía si no existe.
     */
    public static function get(string $name, array $attrs = []): string
    {
        if (! isset(self::$icons[$name])) {
            return '';
        }
        $svg = self::$icons[$name];
        if (empty($attrs)) {
            return $svg;
        }
        // Inyectar atributos en la etiqueta <svg>
        return preg_replace_callback(
            '/<svg(\s*[^>]*)>/i',
            function ($match) use ($attrs) {
                $existing = $match[1];
                foreach ($attrs as $k => $v) {
                    $existing .= sprintf(' %s="%s"', esc_attr($k), esc_attr($v));
                }
                return '<svg' . $existing . '>';
            },
            $svg,
            1
        );
    }
}
